218:     this.paused = false;
219:     this.endingShown = false;
220:     this.time = 0;
221:     this.seed = opts.seed || (mode === 'story' ? 90210 : Math.floor(Math.random() * 900000) + 1000);
222:     this.world = new World(this.seed);
223:     this.renderer = new WorldRenderer(this.world);
224:     this.blood.clear();
225:     this.particles.list.length = 0;
226:     this.enemies = [];
227:     this.props = [];
228:     this.projectiles = [];
