259:     // create props
260:     for (const s of this.world.propSpawns) {
261:       const p = createProp(this, s);
262:       if (!p) continue;
263:       this.props.push(p);
264:       if (s.mission) {
265:         if (s.mission === 'research' && s.type === 'containmentNode') this.missionProps.nodes.push(p);
266:         else if (s.type === 'transitConsole') this.missionProps.subway = p;
267:         else if (s.type === 'evidenceServer') this.missionProps.police = p;
268:         else if (s.type === 'reactorConsole') this.missionProps.power = p;
269:         else if (s.type === 'checkpointGate') this.missionProps.checkpointGate = p;
270:       }
271:     }
272:     // specials
273:     for (const s of this.world.special) {
274:       if (s.type === 'note' || s.type === 'cache' || s.type === 'camo') {
275:         const p = new Pickup(this, s.type, s.x, s.y, { note: s.note });
276:         this.pickups.push(p);
277:       }
278:     }
279:     // preplaced humans
280:     let humanCount = 0;
281:     for (const s of this.world.humanSpawns) {
282:       if (humanCount > 150) break;
283:       const e = new Human(this, s.type, s.x, s.y, s);
284:       if (this.world.rectSolid(e.x - 8, e.y - 40, 16, 38)) continue;
285:       this.enemies.push(e);
286:       humanCount++;
287:     }
288:     // bosses
289:     const apc = new Boss(this, 'apc', 410 * TILE, STREET * TILE);
290:     const aegis = new Boss(this, 'aegis', 444 * TILE, 71 * TILE);
291:     const omega = new Boss(this, 'omega', 592 * TILE, 71 * TILE);
292:     this.bosses = { apc, aegis, omega };
293:     if (mode !== 'survival') {
294:       this.enemies.push(apc, aegis, omega);
295:     }
296: 
297:     let sx = 10 * TILE, sy = 102 * TILE;
298:     if (mode === 'freeroam') { sx = 198 * TILE; sy = STREET * TILE; }
299:     if (mode === 'survival') { sx = 198 * TILE; sy = STREET * TILE; }
300:     this.player = new Player(this, sx, sy);
301:     if (mode === 'freeroam' || mode === 'survival') this.applyLevel(this.player, 2);
302:     if (mode === 'survival') {
303:       this.player.maxHp = 220; this.player.hp = 220;
304:       this.player.abilities.spit = true; this.player.abilities.tendrils = false;
305:       this.threat = 4;
306:     }
307:     this.camera.x = clamp(sx - 480, 0, this.world.width - 960);
308:     this.camera.y = clamp(sy - 320, 0, this.world.height - 540);
309:     this.camera.tx = this.camera.x; this.camera.ty = this.camera.y;
310:     this.input.showTouch(matchMedia('(pointer: coarse)').matches);
311: 
312:     if (mode === 'story') {
313:       this.state = 'intro';
314:       this.showScreen('intro-screen');
315:     } else {
316:       this.hideScreens();
317:       this.announceDistrict(true);
318:       if (mode === 'survival') {
319:         this.notify('SURVIVAL — CONTAINMENT WAVES', 'boss');
320:         this.addSubtitle('Survive. Feed. Evolve. The city is sending everything it has.', 4);
321:         this.spawnSurvivalWave();
322:       } else {
323:         this.notify('FREE ROAM — ALL DISTRICTS OPEN', 'evolution');
324:         this.addSubtitle('The city is yours. No objectives. No mercy.', 3.5);
325:       }
326:     }
327:     this.saveRun();
328:     this.audio.setEnabled(true);
329:     this.updateAudioButton();
