332:   applyLevel(p, level) {
333:     p.level = level;
334:     p.scale = [0.82, 1.0, 1.18, 1.4][level - 1];
335:     p.w = p.baseW * p.scale;
336:     p.h = p.baseH * p.scale;
337:     p.maxHp = 100 + (level - 1) * 45;
338:     p.hp = p.maxHp;
339:     p.maxEnergy = 100 + (level - 1) * 15;
340:     p.energy = p.maxEnergy;
341:     p.abilities.dash = level >= 2;
342:     p.abilities.slam = level >= 2;
343:     p.abilities.spit = level >= 3;
344:     p.abilities.tendrils = level >= 4;
345:     p.squeezeAllowed = level < 3;
346:   }
