356:   playerDeath() {
357:     if (this.state === 'dead') return;
358:     this.state = 'dead';
359:     this.paused = false;
360:     this.input.showTouch(false);
361:     const ds = document.getElementById('death-text');
362:     if (ds) {
363:       if (this.mode === 'survival') ds.textContent = `You survived ${this.survivalWave} waves and killed ${this.stats.kills} before the containment teams put you down.`;
364:       else if (this.mode === 'freeroam') ds.textContent = `The city held. This time. Your rampage killed ${this.stats.kills} and consumed ${this.stats.eaten}.`;
365:       else ds.textContent = 'They scraped what was left of you into a bag and called it a victory. The city will rebuild. It will not forget.';
366:     }
367:     this.showScreen('death-screen');
368:     this.audio.setEnabled(false);
369:   }
