371:   // ---------- UI ----------
372:   _bindUI() {
373:     document.querySelectorAll('[data-action]').forEach((btn) => {
374:       btn.addEventListener('click', async (e) => {
375:         e.preventDefault();
376:         await this.audio.init();
377:         this.audio.sfx('ui');
378:         this.action(btn.dataset.action);
379:       });
380:     });
381:     window.addEventListener('keydown', (e) => {
382:       if (e.code === 'Enter') {
383:         if (this.state === 'intro') { this.action('begin'); }
384:         else if (this.state === 'title') { this.action('story'); }
385:       }
386:       if (e.code === 'Escape') {
387:         if (this.state === 'playing' || this.paused) {
388:           if (this.mapOpen) { this.closeMap(); }
389:           else if (this.noteOpen) { this.closeNote(); }
390:           else if (this.helpOpen) { this.closeHelp(); }
391:           else this.togglePause();
392:         } else if (this.state === 'intro') { this.action('begin'); }
393:       }
394:       if (e.code === 'Tab' && (this.state === 'playing' || this.paused)) {
395:         e.preventDefault();
396:         if (this.mapOpen) this.closeMap(); else this.openMap();
397:       }
398:       if (e.code === 'KeyM') {
399:         this.audio.toggle();
400:         this.updateAudioButton();
401:       }
402:     });
403:   }
404: 
405:   action(a) {
406:     switch (a) {
407:       case 'story': this.startRun('story'); break;
408:       case 'freeroam': this.startRun('freeroam'); break;
409:       case 'survival': this.startRun('survival'); break;
410:       case 'begin': this.hideScreens(); this.state = 'playing'; this.announceDistrict(true); break;
411:       case 'help': this.openHelp(); break;
412:       case 'close-help': this.closeHelp(); break;
413:       case 'resume': this.resume(); break;
414:       case 'quit': this.returnTitle(); break;
415:       case 'retry': this.startRun(this.mode, { seed: this.seed }); break;
416:       case 'toggle-audio': this.audio.toggle(); this.updateAudioButton(); break;
417:       case 'toggle-shake':
418:         this.shakeEnabled = !this.shakeEnabled;
419:         document.querySelector('[data-action="toggle-shake"]').textContent = `Screen Shake: ${this.shakeEnabled ? 'ON' : 'OFF'}`;
420:         break;
421:       case 'close-note': this.closeNote(); break;
422:       case 'continue': this.continueRun(); break;
423:     }
424:   }
