426:   updateAudioButton() {
427:     const el = document.getElementById('audio-state');
428:     if (el) el.textContent = this.audio.enabled ? 'AUDIO: ON — SOUND OF THE CITY' : 'AUDIO: OFF — CLICK TO AWAKEN';
429:     const btn = document.querySelector('[data-action="toggle-audio"]');
430:     if (btn) btn.textContent = this.audio.enabled ? 'Toggle Audio: ON' : 'Toggle Audio: OFF';
431:   }
