433:   showScreen(id) {
434:     document.querySelectorAll('.screen').forEach((s) => s.classList.add('hidden'));
435:     const el = document.getElementById(id);
436:     if (el) el.classList.remove('hidden');
437:   }
438:   hideScreens() {
439:     document.querySelectorAll('.screen').forEach((s) => s.classList.add('hidden'));
440:   }
