442:   togglePause() {
443:     if (this.state !== 'playing') return;
444:     this.paused = !this.paused;
445:     if (this.paused) {
446:       this.updatePauseStats();
447:       this.showScreen('pause-screen');
448:       this.input.showTouch(false);
449:     } else this.resume();
450:   }
451:   resume() {
452:     this.paused = false;
453:     this.hideScreens();
454:     this.input.showTouch(matchMedia('(pointer: coarse)').matches);
455:   }
456:   updatePauseStats() {
457:     const el = document.getElementById('pause-stats');
458:     if (!el) return;
459:     const m = this.currentMission();
460:     el.innerHTML = `DISTRICT <b>${this.currentDistrict()?.name || '—'}</b><br>` +
461:       `FORM <b>${this.player?.level || 1}</b> &nbsp; BIOMASS <b>${Math.ceil(this.player?.hp || 0)}</b><br>` +
462:       `THREAT <b>${this.threatLevel} — ${THREAT_LABELS[this.threatLevel]}</b><br>` +
463:       `KILLS <b>${this.stats.kills}</b> &nbsp; CONSUMED <b>${this.stats.eaten}</b><br>` +
464:       `DOCUMENTS <b>${this.notesFound.size}/6</b> &nbsp; CACHES <b>${this.cachesFound.size}/8</b>` +
465:       (m ? `<br>OBJECTIVE <b>${m.title}</b>` : '');
466:   }
467:   openHelp() {
468:     this.helpOpen = true;
469:     if (this.state === 'playing') this.paused = true;
470:     this.showScreen('help-screen');
