20:       if (d < bd && this.world.lineOfSight(p.x, p.centerY, e.x, e.y - e.h / 2)) { bd = d; best = e; }
21:     }
22:     if (best) {
23:       ax = best.x - p.x;
24:       ay = (best.y - best.h / 2) - p.centerY;
25:     } else {
26:       ax = p.facing * 100;
27:       ay = 0;
28:     }
29:     if (this.input.moveY < -0.5) { ax = p.facing * 40; ay = -100; }
30:     if (this.input.moveY > 0.5 && p.grounded) { ax = p.facing * 100; ay = 0; }
31:   }
32:   const len = Math.hypot(ax, ay);
33:   if (len < 1) { ax = p.facing; ay = 0; }
34:   else { ax /= len; ay /= len; }
35:   return { x: ax, y: ay, angle: Math.atan2(ay, ax) };
36: };
