38: // ==================== RENDER ====================
39: Game.prototype.render = function () {
40:   const ctx = this.ctx;
41:   ctx.setTransform(1, 0, 0, 1, 0, 0);
42:   ctx.imageSmoothingEnabled = false;
43:   ctx.clearRect(0, 0, 960, 540);
44:   if (!this.world) return;
45: 
46:   if (this.state === 'title') {
47:     this.renderTitleScene(ctx);
48:     return;
49:   }
50: 
51:   const cam = this.camera.view;
52:   const zoom = this.camera.zoom || 1;
53:   ctx.save();
54:   if (Math.abs(zoom - 1) > 0.002) {
55:     ctx.translate(480, 270);
56:     ctx.scale(zoom, zoom);
57:     ctx.translate(-480, -270);
58:   }
59:   this.renderScene(ctx, cam);
60:   ctx.restore();
61: 
62:   if (this.screenFlash > 0) {
63:     ctx.fillStyle = `rgba(120,8,14,${Math.min(0.4, this.screenFlash * 0.5)})`;
64:     ctx.fillRect(0, 0, 960, 540);
65:   }
66:   if (this.lightning > 0) {
67:     ctx.fillStyle = `rgba(190,210,230,${this.lightning * 0.35})`;
68:     ctx.fillRect(0, 0, 960, 540);
69:   }
70: 
71:   if (this.state === 'playing' || this.state === 'paused' || this.state === 'dead' || this.state === 'endingChoice' || this.state === 'ending') {
72:     this.drawHUD(ctx, cam);
73:   }
74:   if (this.state === 'intro') this.drawHUD(ctx, cam, true);
75: };
