77: Game.prototype.renderTitleScene = function (ctx) {
78:   const cam = { x: this.camera.x, y: this.camera.y };
79:   const district = this.world.districtAtPx(cam.x + 480);
80:   const underground = false;
81:   this.renderer.drawSky(ctx, cam, district, this.time, underground);
82:   this.renderer.draw(ctx, cam, this.time, district, underground);
83:   this.blood.render(ctx, cam);
84:   for (const c of this.corpses) c.render(ctx, cam, this.time);
85:   for (const p of this.props) p.render(ctx, cam, this.time);
86:   for (const f of this.fires) f.render(ctx, cam, this.time);
87:   if (this.player) this.player.render(ctx, cam, this.time);
88:   this.particles.draw(ctx, cam);
89:   this.drawRain(ctx, district, false);
90:   const lights = this.buildLights(cam);
91:   const ambient = clamp((district.ambient || 0.6) + 0.05, 0, 0.92);
92:   this.lighting.render(ctx, cam, lights, ambient);
93:   // title mood wash
94:   ctx.fillStyle = 'rgba(4,6,9,0.18)';
95:   ctx.fillRect(0, 0, 960, 540);
96: };
