98: Game.prototype.renderScene = function (ctx, cam) {
99:   const district = this.world.districtAtPx(cam.x + 480);
100:   const underground = this.player ? this.player.y > 88 * TILE : cam.y > 86 * TILE;
101:   this.renderer.drawSky(ctx, cam, district, this.time, underground);
102:   this.renderer.draw(ctx, cam, this.time, district, underground);
103:   this.blood.render(ctx, cam);
104:   for (const c of this.corpses) c.render(ctx, cam, this.time);
105:   for (const p of this.props) if (p.alive) p.render(ctx, cam, this.time);
106:   for (const pk of this.pickups) if (!pk.taken) pk.render(ctx, cam, this.time);
107:   for (const f of this.fires) f.render(ctx, cam, this.time);
108:   for (const t of this.tendrils) t.render(ctx, cam, this.time);
109:   for (const e of this.enemies) {
110:     if (e.alive) e.render(ctx, cam, this.time);
111:   }
112:   if (this.player && !this.player.dead) this.player.render(ctx, cam, this.time);
113:   for (const pr of this.projectiles) pr.render(ctx, cam, this.time);
114:   this.particles.draw(ctx, cam);
115:   this.drawRain(ctx, district, underground);
116:   const lights = this.buildLights(cam);
117:   let ambient = district.ambient || 0.6;
118:   if (underground) ambient = 0.9;
119:   else if (this.player && this.world.isBg(Math.floor(this.player.x / TILE), Math.floor(this.player.centerY / TILE))) ambient += 0.1;
120:   if (this.threat >= 4) ambient = Math.min(0.96, ambient + 0.035);
121:   if (this.lightning > 0) ambient = Math.max(0.2, ambient - this.lightning);
122:   this.lighting.render(ctx, cam, lights, clamp(ambient, 0, 0.96));
123:   this.drawObjectiveMarker(ctx, cam);
124: };
