126: Game.prototype.drawRain = function (ctx, district, underground) {
127:   if (underground || !district?.rain) return;
128:   ctx.save();
129:   ctx.strokeStyle = 'rgba(160,190,200,0.16)';
130:   ctx.lineWidth = 1;
131:   ctx.beginPath();
132:   for (const r of this.rain) {
133:     ctx.moveTo(r.x, r.y);
134:     ctx.lineTo(r.x - r.len * 0.18, r.y + r.len);
135:   }
136:   ctx.stroke();
137:   ctx.restore();
138: };
