140: Game.prototype.buildLights = function (cam) {
141:   const lights = [];
142:   const cx = cam.x + 480, cy = cam.y + 270;
143:   for (const l of this.world.lights) {
144:     if (Math.abs(l.x - cx) < 1100 && Math.abs(l.y - cy) < 800) lights.push(l);
145:   }
146:   for (const p of this.props) {
147:     if (!p.alive) continue;
148:     const l = p.light();
149:     if (l) lights.push(l);
150:   }
151:   for (const f of this.fires) {
152:     lights.push({ x: f.x, y: f.y - 20, r: 150 * f.size, color: 'rgba(255,130,50,ALPHA)', glow: 0.2, strength: 0.85, flicker: true });
153:   }
154:   for (const f of this.flashes) {
155:     lights.push({ x: f.x, y: f.y, r: f.r, color: f.color, glow: 0.28, strength: 0.95 });
156:   }
157:   if (this.player && !this.player.dead) {
158:     lights.push({ x: this.player.x, y: this.player.centerY, r: 100 + this.player.level * 18, color: 'rgba(190,30,42,ALPHA)', glow: 0.13, strength: 0.55 });
159:   }
160:   for (const e of this.enemies) {
161:     if (!e.alive) continue;
162:     if (e.type === 'helicopter') {
163:       lights.push({ x: e.x, y: e.y + 8, r: 110, color: 'rgba(200,230,255,ALPHA)', glow: 0.2, strength: 0.9, cone: { angle: e.spotlight.angle, len: e.spotlight.len, spread: e.spotlight.spread } });
164:     } else if (e.isBoss && !e.dormant) {
165:       lights.push({ x: e.x, y: e.y - e.h / 2, r: 170, color: e.type === 'omega' ? 'rgba(180,20,30,ALPHA)' : 'rgba(255,80,50,ALPHA)', glow: 0.12, strength: 0.65, flicker: true });
166:     } else if ((e.type === 'police' || e.type === 'swat' || e.type === 'soldier') && !e.grabbed) {
167:       const d = Math.hypot(e.x - cx, e.y - cy);
168:       if (d < 900) lights.push({ x: e.x + e.facing * 14, y: e.y - e.h * 0.7, r: 105, color: 'rgba(200,225,255,ALPHA)', glow: 0.08, strength: 0.55 });
169:     }
170:   }
171:   if (this.threat >= 3) {
172:     const pulse = 0.5 + Math.sin(this.time * 4) * 0.5;
173:     lights.push({ x: cx - 420, y: 120, r: 250, color: 'rgba(255,20,30,ALPHA)', glow: 0.035 * pulse, strength: 0.25 });
174:     lights.push({ x: cx + 420, y: 120, r: 250, color: 'rgba(255,20,30,ALPHA)', glow: 0.035 * pulse, strength: 0.25 });
175:   }
176:   return lights;
177: };
