179: // ==================== HUD ====================
180: Game.prototype.drawHUD = function (ctx, cam, intro = false) {
181:   const p = this.player;
182:   if (!p) return;
183:   const district = this.currentDistrict();
184:   const mission = this.currentMission();
185:   ctx.save();
186:   ctx.imageSmoothingEnabled = false;
187:   ctx.textBaseline = 'top';
188: 
189:   // --- objective panel ---
190:   const panelW = 390, panelH = 64;
191:   this.hudPanel(ctx, 16, 14, panelW, panelH, 0.55);
192:   ctx.fillStyle = '#b3272d';
193:   ctx.font = 'bold 8px "Courier New", monospace';
194:   ctx.textAlign = 'left';
195:   ctx.fillText((district?.name || 'THE CITY') + ' // ' + THREAT_LABELS[this.threatLevel], 28, 24);
196:   ctx.fillStyle = '#e6dfcf';
197:   ctx.font = 'bold 13px "Courier New", monospace';
198:   if (this.mode === 'survival') {
199:     ctx.fillText(`SURVIVAL — WAVE ${this.survivalWave}`, 28, 38);
200:     ctx.fillStyle = '#8d887d'; ctx.font = '9px "Courier New", monospace';
201:     ctx.fillText(`NEXT WAVE IN ${Math.ceil(this.survivalTimer)}s   //   SCORE ${this.survivalScore}`, 28, 56);
202:   } else if (this.mode === 'freeroam') {
203:     ctx.fillText('FREE ROAM — NO OBJECTIVES', 28, 38);
204:     ctx.fillStyle = '#8d887d'; ctx.font = '9px "Courier New", monospace';
205:     ctx.fillText(`DISTRICTS OPEN // DOCUMENTS ${this.notesFound.size}/6 // CACHES ${this.cachesFound.size}/8`, 28, 56);
206:   } else if (mission) {
207:     ctx.fillText(`${mission.title}`, 28, 38);
208:     ctx.fillStyle = '#8d887d'; ctx.font = '9px "Courier New", monospace';
209:     ctx.fillText(mission.desc, 28, 56);
210:   } else {
211:     ctx.fillText('THE CITY IS QUIET', 28, 38);
212:     ctx.fillStyle = '#8d887d'; ctx.font = '9px "Courier New", monospace';
213:     ctx.fillText('The outbreak is over. The consequences are not.', 28, 56);
214:   }
215: 
216:   // --- threat panel ---
217:   const tx = 704, ty = 14, tw = 240, th = 54;
218:   this.hudPanel(ctx, tx, ty, tw, th, 0.55);
219:   ctx.textAlign = 'left';
220:   ctx.font = 'bold 8px "Courier New", monospace';
221:   ctx.fillStyle = '#8d887d';
222:   ctx.fillText('THREAT LEVEL', tx + 12, ty + 10);
223:   ctx.fillStyle = THREAT_COLORS[this.threatLevel];
224:   ctx.font = 'bold 13px "Courier New", monospace';
225:   ctx.fillText(`${this.threatLevel} — ${THREAT_LABELS[this.threatLevel]}`, tx + 12, ty + 22);
226:   for (let i = 0; i < 6; i++) {
227:     const active = this.threat >= i;
228:     ctx.fillStyle = active ? THREAT_COLORS[Math.min(5, i)] : 'rgba(217,210,194,0.13)';
229:     const bx = tx + 12 + i * 35, by = ty + 40;
230:     ctx.beginPath();
231:     ctx.moveTo(bx, by + 7); ctx.lineTo(bx + 8, by); ctx.lineTo(bx + 16, by + 7); ctx.lineTo(bx + 8, by + 14);
232:     ctx.closePath(); ctx.fill();
233:   }
234: 
235:   // --- minimap ---
236:   this.hudMinimap(ctx, tx, ty + th + 6, tw, 54);
237: 
238:   // --- biomass / form ---
239:   const bx = 20, by = 470, bw = 282;
240:   this.hudPanel(ctx, bx, by, bw, 56, 0.6);
241:   ctx.textAlign = 'left';
242:   ctx.font = 'bold 8px "Courier New", monospace';
243:   ctx.fillStyle = '#8d887d';
244:   ctx.fillText(`BIOMASS // FORM ${p.level}`, bx + 10, by + 8);
245:   ctx.textAlign = 'right';
246:   ctx.fillStyle = '#e6dfcf';
247:   ctx.fillText(`${Math.ceil(p.hp)} / ${Math.ceil(p.maxHp)}`, bx + bw - 10, by + 8);
248:   ctx.textAlign = 'left';
249:   const hpw = bw - 20;
250:   ctx.fillStyle = 'rgba(30,6,9,0.9)';
251:   ctx.fillRect(bx + 10, by + 22, hpw, 12);
252:   const hpGrad = ctx.createLinearGradient(bx + 10, 0, bx + 10 + hpw, 0);
253:   hpGrad.addColorStop(0, '#6e0c14');
254:   hpGrad.addColorStop(0.7, '#b3272d');
255:   hpGrad.addColorStop(1, '#e0353f');
256:   ctx.fillStyle = hpGrad;
257:   ctx.fillRect(bx + 10, by + 22, hpw * clamp(p.hp / p.maxHp, 0, 1), 12);
258:   ctx.fillStyle = 'rgba(0,0,0,0.35)';
259:   for (let i = 1; i < 4; i++) ctx.fillRect(bx + 10 + hpw * i / 4, by + 22, 1, 12);
260:   ctx.fillStyle = 'rgba(255,255,255,0.13)';
261:   ctx.fillRect(bx + 10, by + 22, hpw * clamp(p.hp / p.maxHp, 0, 1), 2);
262:   // energy
263:   ctx.fillStyle = 'rgba(30,40,36,0.9)';
264:   ctx.fillRect(bx + 10, by + 40, hpw, 5);
265:   ctx.fillStyle = '#9fbf73';
266:   ctx.fillRect(bx + 10, by + 40, hpw * clamp(p.energy / p.maxEnergy, 0, 1), 5);
267:   ctx.fillStyle = '#8d887d';
268:   ctx.font = '7px "Courier New", monospace';
269:   ctx.fillText(`BIO-ENERGY ${Math.ceil(p.energy)}`, bx + 10, by + 47);
270: 
271:   // --- abilities ---
272:   this.drawAbilities(ctx, 690, 400);
273: 
274:   // --- boss bar ---
275:   if (this.boss && this.boss.alive && !this.boss.dormant) {
276:     const b = this.boss;
277:     const w = 440, x = 260, y = 18;
278:     this.hudPanel(ctx, x, y, w, 38, 0.7);
279:     ctx.textAlign = 'left';
280:     ctx.font = 'bold 8px "Courier New", monospace';
281:     ctx.fillStyle = '#e0353f';
282:     ctx.fillText(b.name, x + 12, y + 8);
283:     ctx.fillStyle = 'rgba(30,6,9,0.9)';
284:     ctx.fillRect(x + 12, y + 22, w - 24, 8);
285:     ctx.fillStyle = '#b3272d';
286:     ctx.fillRect(x + 12, y + 22, (w - 24) * clamp(b.hp / b.maxHp, 0, 1), 8);
287:     ctx.fillStyle = 'rgba(255,255,255,0.16)';
288:     ctx.fillRect(x + 12, y + 22, (w - 24) * clamp(b.hp / b.maxHp, 0, 1), 1);
289:     ctx.textAlign = 'right';
290:     ctx.fillStyle = '#8d887d';
291:     ctx.fillText(`PHASE ${b.phase}`, x + w - 12, y + 8);
292:   }
293: 
294:   // --- notifications ---
295:   let ny = 88;
296:   ctx.textAlign = 'center';
297:   for (const n of this.notifications) {
298:     const a = Math.min(1, n.life / 0.6);
299:     ctx.globalAlpha = a;
300:     ctx.font = 'bold 9px "Courier New", monospace';
301:     const col = n.type === 'boss' ? '#e0353f' : n.type === 'threat' ? '#e0a25a' : n.type === 'evolution' ? '#9fbf73' : n.type === 'objective' ? '#e6dfcf' : n.type === 'district' ? '#8ee8f2' : '#b9b3a5';
302:     const tw2 = Math.max(160, ctx.measureText(n.text).width + 24);
303:     ctx.fillStyle = 'rgba(4,6,9,0.55)';
304:     ctx.fillRect(480 - tw2 / 2, ny, tw2, 18);
305:     ctx.fillStyle = col;
306:     ctx.fillText(n.text, 480, ny + 5);
307:     ny += 22;
308:     if (ny > 240) break;
309:   }
310:   ctx.globalAlpha = 1;
311: 
312:   // --- district banner ---
313:   if (this.districtBanner) {
314:     const b = this.districtBanner;
315:     const a = Math.min(1, b.life, (4.2 - b.life) * 2);
316:     ctx.globalAlpha = Math.max(0, a);
317:     ctx.textAlign = 'center';
318:     ctx.fillStyle = '#e6dfcf';
319:     ctx.font = 'bold 24px "Courier New", monospace';
320:     ctx.fillText(b.name, 480, 146);
321:     ctx.fillStyle = '#b3272d';
322:     ctx.font = 'bold 9px "Courier New", monospace';
323:     ctx.fillText(b.sub, 480, 176);
324:     ctx.fillStyle = 'rgba(166,31,39,0.55)';
325:     ctx.fillRect(380, 190, 200, 1);
326:     ctx.globalAlpha = 1;
327:   }
328: 
329:   // --- interaction prompt ---
330:   this.drawInteractionPrompt(ctx, cam);
331: 
332:   // --- subtitles ---
333:   if (this.subtitles.length) {
334:     const s = this.subtitles[this.subtitles.length - 1];
335:     const a = Math.min(1, s.life / 0.5);
336:     ctx.globalAlpha = a;
337:     ctx.font = '10px "Courier New", monospace';
338:     ctx.textAlign = 'center';
339:     const maxW = 640;
340:     const lines = this.wrapText(ctx, s.text, maxW);
341:     const h = lines.length * 14 + 12;
342:     ctx.fillStyle = 'rgba(4,6,9,0.62)';
343:     ctx.fillRect(480 - maxW / 2, 444 - h, maxW, h);
344:     ctx.fillStyle = '#b9b3a5';
345:     lines.forEach((line, i) => ctx.fillText(line, 480, 438 - h + i * 14));
346:     ctx.globalAlpha = 1;
347:   }
348: 
349:   // --- hints ---
350:   if (this.mode === 'story' && this.missionIndex === 0 && this.time < 22) {
351:     ctx.textAlign = 'center';
352:     ctx.fillStyle = 'rgba(217,210,194,0.55)';
353:     ctx.font = '9px "Courier New", monospace';
354:     ctx.fillText('MOVE A/D  ·  CLIMB W  ·  LEAP SPACE  ·  WHIP J  ·  GRAB K  ·  DEVOUR E  ·  ZIP Q', 480, 420);
355:   }
356: 
357:   ctx.restore();
358: };
