370: Game.prototype.drawAbilities = function (ctx, x, y) {
371:   const p = this.player;
372:   const list = [
373:     { key: 'J', name: 'WHIP', on: true },
374:     { key: 'K', name: 'GRAB', on: true },
375:     { key: 'E', name: 'DEVOUR', on: true },
376:     { key: 'Q', name: 'ZIP', on: true },
377:     { key: '⇧', name: 'DASH', on: p.abilities.dash },
378:     { key: 'X', name: 'SLAM', on: p.abilities.slam },
379:     { key: 'F', name: 'SPIT', on: p.abilities.spit },
380:     { key: 'R', name: 'TENDRIL', on: p.abilities.tendrils },
381:     { key: 'C', name: 'CAMO', on: p.abilities.camo },
382:   ];
383:   const cw = 80, ch = 23;
384:   for (let i = 0; i < list.length; i++) {
385:     const a = list[i];
386:     const col = i % 3, row = Math.floor(i / 3);
387:     const bx = x + col * (cw + 4), by = y + row * (ch + 3);
388:     ctx.fillStyle = a.on ? 'rgba(10,14,18,0.68)' : 'rgba(10,14,18,0.3)';
389:     ctx.fillRect(bx, by, cw, ch);
390:     ctx.strokeStyle = a.on ? 'rgba(217,210,194,0.18)' : 'rgba(217,210,194,0.06)';
391:     ctx.strokeRect(bx + 0.5, by + 0.5, cw - 1, ch - 1);
392:     ctx.fillStyle = a.on ? '#b3272d' : 'rgba(141,136,125,0.3)';
393:     ctx.font = 'bold 10px "Courier New", monospace';
394:     ctx.textAlign = 'center';
395:     ctx.fillText(a.key, bx + 12, by + 7);
396:     ctx.fillStyle = a.on ? '#d9d2c2' : 'rgba(141,136,125,0.3)';
397:     ctx.font = 'bold 7px "Courier New", monospace';
398:     ctx.fillText(a.name, bx + 46, by + 8);
399:     if (!a.on) {
400:       ctx.strokeStyle = 'rgba(166,31,39,0.35)';
401:       ctx.beginPath(); ctx.moveTo(bx + 4, by + ch - 4); ctx.lineTo(bx + cw - 4, by + 4); ctx.stroke();
402:     }
403:   }
404:   // current form
405:   ctx.textAlign = 'right';
406:   ctx.font = '7px "Courier New", monospace';
407:   ctx.fillStyle = '#8d887d';
408:   ctx.fillText(`FORM ${p.level} // XP ${Math.floor(p.xp)}`, x + 252, y - 10);
409: };
