411: Game.prototype.hudMinimap = function (ctx, x, y, w, h) {
412:   ctx.fillStyle = 'rgba(4,6,9,0.55)';
413:   ctx.fillRect(x, y, w, h);
414:   ctx.strokeStyle = 'rgba(217,210,194,0.12)';
415:   ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
416:   const pad = 6;
417:   const mw = w - pad * 2, mh = h - pad * 2;
418:   for (const d of DISTRICTS) {
419:     const dx = x + pad + (d.x0 / 600) * mw;
420:     const dw = ((d.x1 - d.x0) / 600) * mw;
421:     const panic = this.panic[d.id] || 0;
422:     ctx.fillStyle = `rgba(${60 + panic * 1.4},${40 - panic * 0.1},${45 - panic * 0.1},0.6)`;
423:     ctx.fillRect(dx, y + pad, Math.max(1, dw - 1), mh * 0.55);
424:     ctx.fillStyle = 'rgba(100,140,150,0.18)';
425:     ctx.fillRect(dx, y + pad + mh * 0.62, Math.max(1, dw - 1), mh * 0.2);
426:   }
427:   if (this.player) {
428:     const px = x + pad + clamp(this.player.x / this.world.width, 0, 1) * mw;
