1115:   updatePhysics(dt) {
1116:     this.vy += 1350 * dt;
1117:     if (this.vy > 900) this.vy = 900;
1118:     let dx = this.vx * dt;
1119:     const stepsX = Math.max(1, Math.ceil(Math.abs(dx) / 4));
1120:     const sx = dx / stepsX;
1121:     for (let i = 0; i < stepsX; i++) {
1122:       const nx = this.x + sx;
1123:       if (this.game.rectBlocked(nx - this.w / 2, this.y - this.h + 2, this.w, this.h - 4)) {
1124:         this.vx = 0;
1125:         if (this.grounded && !this.grabbed && this.state !== 'flee' && Math.random() < 0.3) this.vy = -380;
1126:         break;
1127:       }
1128:       this.x = nx;
1129:     }
1130:     let dy = this.vy * dt;
1131:     const stepsY = Math.max(1, Math.ceil(Math.abs(dy) / 4));
1132:     const sy = dy / stepsY;
1133:     this.grounded = false;
1134:     for (let i = 0; i < stepsY; i++) {
1135:       const ny = this.y + sy;
1136:       if (this.game.rectBlocked(this.x - this.w / 2 + 2, ny - this.h, this.w - 4, this.h)) {
1137:         if (this.vy > 0) this.grounded = true;
1138:         this.vy = 0;
1139:         break;
1140:       }
1141:       this.y = ny;
1142:       if (this.vy > 0) {
1143:         const ty = Math.floor((this.y + 1) / TILE);
1144:         const x0 = Math.floor((this.x - this.w / 2 + 2) / TILE);
1145:         const x1 = Math.floor((this.x + this.w / 2 - 2) / TILE);
1146:         for (let tx = x0; tx <= x1; tx++) {
1147:           if (this.game.world.isPlatform(tx, ty)) { this.y = ty * TILE; this.vy = 0; this.grounded = true; break; }
1148:         }
1149:       }
1150:     }
1151:     this.x = clamp(this.x, 20, this.game.world.width - 20);
1152:     if (this.y > this.game.world.height + 100) this.alive = false;
1153:   }
1154: 
1155:   fire() {
1156:     const p = this.game.player;
1157:     if (!p || p.dead) return;
1158:     const gx = this.x + this.facing * 10;
1159:     const gy = this.centerY - 2;
1160:     let tx = p.x, ty = p.centerY;
1161:     const spread = this.type === 'elite' ? 0.12 : this.type === 'heavy' ? 0.11 : 0.055;
1162:     const a = Math.atan2(ty - gy, tx - gx) + (Math.random() - 0.5) * spread * 2;
1163:     const speed = this.type === 'heavy' ? 720 : 760;
1164:     this.game.projectiles.push(new Projectile(this.game, gx, gy, Math.cos(a) * speed, Math.sin(a) * speed, {
1165:       owner: 'enemy', type: 'bullet', damage: this.cfg.dmg, life: 1.1, color: '#ffd27a', radius: 3,
1166:     }));
1167:     this.game.particles.sparks(gx + this.facing * 6, gy, 3, '#ffd27a');
1168:     this.game.particles.shell(gx, gy);
1169:     this.game.addFlash(gx, gy, 70, 'rgba(255,200,120,ALPHA)', 0.06);
1170:     this.game.audio.sfx(this.type === 'police' ? 'gun' : 'rifle', gx, gy);
1171:     if (this.type === 'soldier' && Math.random() < 0.08) {
1172:       this.game.projectiles.push(new Projectile(this.game, gx, gy, Math.cos(a) * 380, Math.sin(a) * 380 - 100, {
1173:         owner: 'enemy', type: 'grenade', damage: 30, life: 2.2, color: '#5a6a3a', radius: 6,
1174:       }));
1175:     }
1176:   }
1177: 
1178:   damage(amount, game, dirX = 0, dirY = 0, source = null) {
