1349: // ===================== PROJECTILES =====================
1350: export class Projectile {
1351:   constructor(game, x, y, vx, vy, opts) {
1352:     this.game = game;
1353:     this.x = x; this.y = y; this.vx = vx; this.vy = vy;
1354:     this.owner = opts.owner || 'enemy';
1355:     this.type = opts.type || 'bullet';
1356:     this.damage = opts.damage || 5;
1357:     this.radius = opts.radius || 3;
1358:     this.life = opts.life || 1.2;
1359:     this.maxLife = this.life;
1360:     this.color = opts.color || '#ffd27a';
1361:     this.alive = true;
1362:     this.gravity = this.type === 'grenade' ? 900 : 0;
1363:     this.bounce = 0;
1364:   }
1365:   update(dt) {
1366:     if (!this.alive) return;
1367:     this.life -= dt;
1368:     if (this.life <= 0) { this.alive = false; return; }
1369:     this.vy += this.gravity * dt;
1370:     const nx = this.x + this.vx * dt;
1371:     const ny = this.y + this.vy * dt;
1372:     const hit = this.game.world.solidAtPx(nx, ny);
1373:     if (hit) {
1374:       if (this.type === 'grenade') { this.vy = -Math.abs(this.vy) * 0.45; this.vx *= 0.7; this.bounce++; if (this.bounce > 3) { this.explode(); return; } }
1375:       else { this.impact(nx, ny, true); return; }
1376:     } else { this.x = nx; this.y = ny; }
1377:     if (this.type === 'grenade' && this.life < 0.1) { this.explode(); return; }
1378:     const p = this.game.player;
1379:     if (this.owner === 'enemy') {
1380:       if (p && !p.dead && Math.abs(p.x - this.x) < p.w / 2 + this.radius && Math.abs(p.centerY - this.y) < p.h / 2 + this.radius) {
1381:         p.damage(this.damage, this.game, this.vx, this.vy);
1382:         this.impact(this.x, this.y, false);
1383:       }
1384:     } else {
1385:       for (const e of this.game.enemies) {
1386:         if (!e.alive) continue;
1387:         if (Math.abs(e.x - this.x) < e.w / 2 + this.radius && Math.abs((e.y - e.h / 2) - this.y) < e.h / 2 + this.radius) {
1388:           e.damage(this.damage, this.game, Math.sign(this.vx), Math.sign(this.vy), this);
1389:           this.game.particles.gore(this.x, this.y, Math.sign(this.vx), 0, 0.8);
1390:           this.impact(this.x, this.y, false);
1391:           break;
1392:         }
1393:       }
1394:     }
1395:     if (this.type === 'spit' && Math.random() < 0.6) this.game.particles.slime(this.x, this.y, 0);
1396:     if (this.type === 'rocket' && Math.random() < 0.8) this.game.particles.smoke(this.x, this.y, 1);
1397:   }
1398:   explode() {
1399:     this.alive = false;
1400:     this.game.explode(this.x, this.y, 95, this.damage, this, 1.8);
1401:   }
1402:   impact(x, y, wall) {
1403:     this.alive = false;
1404:     if (this.type === 'rocket' || this.type === 'grenade') { this.explode(); return; }
1405:     this.game.particles.sparks(x, y, 4, this.color);
1406:     if (this.type === 'spit') { this.game.blood.splat(x, y, 1.2, this.vx, this.vy); this.game.particles.blood(x, y, this.vx, this.vy, 0.8); }
1407:     if (wall) this.game.particles.debris(x, y, 2, '#5a5550');
1408:   }
1409:   render(ctx, cam, time) {
1410:     if (!this.alive) return;
1411:     const x = this.x - cam.x, y = this.y - cam.y;
1412:     if (x < -30 || x > 990 || y < -30 || y > 570) return;
1413:     if (this.type === 'bullet') {
1414:       ctx.strokeStyle = this.color;
1415:       ctx.lineWidth = 1.5;
1416:       ctx.globalAlpha = 0.9;
1417:       ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - this.vx * 0.012, y - this.vy * 0.012); ctx.stroke();
1418:       ctx.globalAlpha = 1;
1419:     } else if (this.type === 'grenade') {
1420:       ctx.fillStyle = this.color;
1421:       ctx.beginPath(); ctx.arc(x, y, 4, 0, 7); ctx.fill();
1422:       ctx.fillStyle = '#ffd27a'; ctx.fillRect(x - 1, y - 5, 2, 2);
1423:     } else if (this.type === 'spit') {
1424:       ctx.fillStyle = 'rgba(140,20,30,0.4)';
1425:       ctx.beginPath(); ctx.arc(x, y, this.radius * 1.8, 0, 7); ctx.fill();
1426:       ctx.fillStyle = '#8a1019';
1427:       ctx.beginPath(); ctx.arc(x, y, this.radius, 0, 7); ctx.fill();
1428:       ctx.fillStyle = '#d94a4a';
1429:       ctx.beginPath(); ctx.arc(x - 2, y - 2, 2, 0, 7); ctx.fill();
1430:     } else {
1431:       ctx.fillStyle = this.color;
1432:       ctx.beginPath(); ctx.arc(x, y, 3, 0, 7); ctx.fill();
1433:     }
1434:   }
1435: }
