227:       this.fill(cx, cy - 1, cx + w, cy - 1, T.SEWER);
228:       this.fill(cx - 1, cy, cx - 1, cy + h, T.SEWER);
229:       this.fill(cx + w + 1, cy, cx + w + 1, cy + h, T.SEWER);
230:       if (kind === 'cache') this.special.push({ type: 'cache', x: (cx + w / 2) * TILE, y: (cy + h + 1) * TILE, district: 'underground' });
231:       if (kind === 'lab') this.special.push({ type: 'note', note: 2, x: (cx + 2) * TILE, y: (cy + h + 1) * TILE, district: 'underground' });
232:       if (kind === 'armory') this.propSpawns.push({ type: 'ammoCrate', x: (cx + 2) * TILE, y: (cy + h + 1) * TILE, district: 'underground' });
233:     }
