238:     // shafts (street to sewer)
239:     const shaftXs = [49, 61, 101, 128, 148, 202, 248, 318, 400, 482, 524, 558];
240:     for (const sx of shaftXs) this.carveShaft(sx, 2, false);
241:     // basement shafts inside landmarks
