253:     // ambient lights
254:     this.lights.push({ x: 20 * TILE, y: 96 * TILE, r: 120, color: 'rgba(120,190,120,ALPHA)', glow: 0.06, strength: 0.5, flicker: true });
255:     this.lights.push({ x: 500 * TILE, y: 96 * TILE, r: 120, color: 'rgba(120,190,120,ALPHA)', glow: 0.06, strength: 0.5, flicker: true });
256:   }
