310:   buildBuilding(d, r) {
311:     const { x, w, top, bg } = d;
312:     const style = d.style;
313:     const wallType = style === 'industrial' || style === 'harbor' ? T.METAL
314:       : style === 'downtown' || style === 'police' || style === 'research' ? T.CONCRETE
315:       : style === 'military' ? T.CONCRETE : T.BRICK;
316:     const floorH = d.floors <= 2 ? 9 : d.floors >= 7 ? 7 : 8;
317:     this.buildings.push({ ...d, wallType, floorH });
318: 
319:     // interior background
320:     this.fill(x + 1, top + 1, x + w - 2, STREET - 1, bg);
321:     // walls
322:     for (let y = top; y < STREET; y++) {
323:       this.set(x, y, wallType);
324:       this.set(x + w - 1, y, wallType);
325:     }
326:     // roof
327:     for (let xx = x; xx < x + w; xx++) { this.set(xx, top, T.ROOF); this.set(xx, top + 1, T.ROOF); }
328:     // interior ceilings under roof
329:     for (let xx = x + 1; xx < x + w - 1; xx++) this.set(xx, top + 1, T.ROOF);
330: 
331:     // floors
332:     const floorRows = [];
333:     let fy = top + 2 + floorH;
334:     while (fy < STREET) { floorRows.push(fy); fy += floorH; }
335:     for (const row of floorRows) {
336:       for (let xx = x + 1; xx < x + w - 1; xx++) this.set(xx, row, T.FLOOR);
337:       // stair gap
338:       const gap = x + 3 + Math.floor(r() * (w - 8));
339:       this.set(gap, row, T.EMPTY); this.set(gap + 1, row, T.EMPTY);
340:       // little railing light
341:     }
342:     // windows on side walls
343:     const allFloors = [top + 2, ...floorRows];
344:     for (const row of allFloors) {
345:       const wy = row - 3;
346:       if (wy > top + 1 && wy < STREET - 1) {
347:         if (r() < 0.8) { this.set(x, wy, T.GLASS); this.set(x + w - 1, wy, T.GLASS); }
348:       }
349:       if (r() < 0.35) {
350:         const wy2 = row - 2;
351:         if (wy2 > top + 1 && wy2 < STREET - 1) { this.set(x, wy2, T.GLASS); this.set(x + w - 1, wy2, T.GLASS); }
352:       }
353:     }
354:     // doors
355:     const sides = [];
356:     if (r() < 0.7) sides.push(0);
357:     if (r() < 0.7 || sides.length === 0) sides.push(1);
358:     for (const s of sides) {
359:       const dx = s === 0 ? x : x + w - 1;
360:       this.set(dx, STREET - 1, T.EMPTY);
361:       this.set(dx, STREET - 2, T.EMPTY);
362:       const closed = r() < (d.doorChance ?? 0.45);
363:       this.propSpawns.push({ type: closed ? 'door' : 'brokenDoor', x: dx * TILE + TILE / 2, y: STREET * TILE, district: this.districtAtPx(x * TILE).id, w: TILE, h: TILE * 2, solid: closed });
364:     }
365:     // roof hatch
366:     const hatch = x + Math.floor(w / 2);
367:     this.set(hatch, top, T.EMPTY); this.set(hatch + 1, top, T.EMPTY);
368:     this.propSpawns.push({ type: 'roofHatch', x: hatch * TILE, y: top * TILE, district: this.districtAtPx(x * TILE).id, w: TILE * 2, h: TILE });
369:     // weak wall
370:     if (w > 8) {
371:       const wx = r() < 0.5 ? x : x + w - 1;
372:       const wy = top + 4 + Math.floor(r() * Math.max(2, STREET - top - 8));
373:       this.set(wx, wy, T.WEAK);
374:     }
375: 
376:     // interior lights & props & humans
377:     const district = this.districtAtPx(x * TILE);
378:     const propPool = this.propPool(style);
379:     for (let fi = 0; fi < allFloors.length; fi++) {
380:       const row = allFloors[fi];
381:       if (row >= STREET - 1) continue;
382:       // ceiling light
383:       if (w > 10 && fi % 2 === 0) {
384:         this.lights.push({ x: (x + Math.floor(w / 2)) * TILE, y: (row - 2) * TILE, r: 100 + w * 1.4, color: 'rgba(255,220,160,ALPHA)', glow: 0.08, strength: 0.7, flicker: r() < 0.35 });
385:       }
386:       const count = 1 + Math.floor(r() * 3);
387:       for (let i = 0; i < count; i++) {
388:         const px = x + 2 + Math.floor(r() * Math.max(1, w - 5));
389:         const prop = propPool[Math.floor(r() * propPool.length)];
390:         this.propSpawns.push({ type: prop, x: px * TILE + TILE / 2, y: row * TILE, district: district.id, floor: fi });
391:       }
392:       // humans
393:       if (style === 'residential' && r() < 0.55) this.humanSpawns.push({ type: 'civilian', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
394:       if (style === 'downtown' && r() < 0.4) this.humanSpawns.push({ type: r() < 0.8 ? 'civilian' : 'police', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
395:       if (style === 'mall' && r() < 0.5) this.humanSpawns.push({ type: 'civilian', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
396:       if (style === 'police' && r() < 0.65) this.humanSpawns.push({ type: r() < 0.55 ? 'police' : 'swat', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
397:       if (style === 'military' && r() < 0.8) this.humanSpawns.push({ type: r() < 0.6 ? 'soldier' : 'heavy', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
398:       if (style === 'research' && r() < 0.5) this.humanSpawns.push({ type: r() < 0.7 ? 'researcher' : 'soldier', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
399:       if (style === 'power' && r() < 0.4) this.humanSpawns.push({ type: 'worker', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
400:       if (style === 'harbor' && r() < 0.35) this.humanSpawns.push({ type: 'worker', x: (x + 2 + r() * (w - 5)) * TILE, y: row * TILE, district: district.id, indoors: true });
401:     }
402: 
403:     // landmark extras
404:     if (d.landmark === 'mall') this.decorateMall(d, r);
405:     if (d.landmark === 'police') this.decoratePolice(d, r);
406:     if (d.landmark === 'research') this.decorateResearch(d, r);
407:     if (d.landmark === 'power') this.decoratePower(d, r);
408:     if (d.landmark === 'apartment') this.decorateApartment(d, r);
409:     if (d.landmark === 'tower') this.decorateTower(d, r);
410:   }
411: 
412:   propPool(style) {
413:     const common = ['chair', 'crate', 'trash', 'plant', 'cabinet'];
414:     switch (style) {
415:       case 'residential': return ['bed', 'sofa', 'tv', 'lamp', 'chair', 'shelf', 'plant', 'fridge'];
416:       case 'downtown': return ['desk', 'chair', 'cabinet', 'plant', 'vending', 'server', 'copier'];
417:       case 'mall': return ['bench', 'plant', 'vending', 'kiosk', 'mannequin', 'sofa', 'trash'];
418:       case 'police': return ['desk', 'chair', 'locker', 'filing', 'cabinet', 'copier', 'bench'];
419:       case 'military': return ['crate', 'locker', 'ammoCrate', 'desk', 'sandbag'];
420:       case 'research': return ['labTank', 'desk', 'server', 'cabinet', 'gurney', 'chair'];
421:       case 'power': return ['crate', 'pipe', 'generator', 'locker', 'barrel'];
422:       case 'harbor': return ['crate', 'barrel', 'pallet', 'pipe', 'locker'];
423:       default: return common;
424:     }
425:   }
