427:   decorateMall(d, r) {
428:     const { x, w, top } = d;
429:     // open atrium in center
430:     const ax = x + Math.floor(w / 2) - 6;
431:     for (let xx = ax; xx < ax + 12; xx++) {
432:       for (let y = top + 3; y < STREET - 2; y++) {
433:         if (this.get(xx, y) === T.FLOOR) this.set(xx, y, T.PLATFORM);
434:       }
435:     }
436:     // escalator platforms
437:     for (let i = 0; i < 10; i++) this.set(ax + i, top + 12 - i, T.PLATFORM);
438:     for (let i = 0; i < 10; i++) this.set(ax + 11 - i, top + 22 + i, T.PLATFORM);
439:     // glass storefronts
440:     for (let y = top + 4; y < STREET - 4; y += 8) {
441:       for (let xx = x + 3; xx < x + w - 4; xx += 9) this.set(xx, y, T.GLASS);
442:     }
443:     this.lights.push({ x: (x + w / 2) * TILE, y: (top + 6) * TILE, r: 240, color: 'rgba(255,210,150,ALPHA)', glow: 0.1, strength: 0.65, flicker: true });
444:     this.propSpawns.push({ type: 'mallSign', x: (x + w / 2) * TILE, y: (top + 2) * TILE, district: 'mall' });
445:     this.special.push({ type: 'note', note: 3, x: (ax + 2) * TILE, y: (STREET - 1) * TILE, district: 'mall' });
446:     this.special.push({ type: 'cache', x: (ax + 8) * TILE, y: (top + 22) * TILE, district: 'mall' });
447:     this.special.push({ type: 'camo', x: (x + w - 4) * TILE, y: (top + 12) * TILE, district: 'mall' });
448:     // hidden basement lab
449:     this.carveRoom(x + 8, 74, 14, 6, T.BG_LAB);
450:     this.special.push({ type: 'note', note: 4, x: (x + 10) * TILE, y: 79 * TILE, district: 'mall' });
451:     this.special.push({ type: 'cache', x: (x + 18) * TILE, y: 79 * TILE, district: 'mall' });
452:     this.humanSpawns.push({ type: 'survivor', x: (x + 20) * TILE, y: 79 * TILE, district: 'mall', indoors: true });
453:   }
