464:     this.propSpawns.push({ type: 'armory', x: (x + 4) * TILE, y: (top + 12) * TILE, district: 'police' });
465:     this.special.push({ type: 'note', note: 5, x: (x + 6) * TILE, y: (top + 28) * TILE, district: 'police' });
466:     this.special.push({ type: 'cache', x: (x + w - 4) * TILE, y: (top + 8) * TILE, district: 'police' });
467:     this.lights.push({ x: (x + 3) * TILE, y: (top + 5) * TILE, r: 90, color: 'rgba(90,150,255,ALPHA)', glow: 0.08, strength: 0.6, flicker: true });
468:     for (let i = 0; i < 4; i++) this.propSpawns.push({ type: 'barricade', x: (x + 2 + i * 3) * TILE, y: STREET * TILE, district: 'police', solid: true });
469:   }
