511:   carveRoom(x, y, w, h, bg) {
512:     this.fill(x, y, x + w, y + h, bg);
513:     this.fill(x, y + h + 1, x + w, y + h + 1, T.SEWER);
514:     this.fill(x, y - 1, x + w, y - 1, T.SEWER);
515:     this.fill(x - 1, y, x - 1, y + h, T.SEWER);
516:     this.fill(x + w + 1, y, x + w + 1, y + h, T.SEWER);
517:     this.lights.push({ x: (x + w / 2) * TILE, y: (y + 1) * TILE, r: 100, color: 'rgba(120,220,180,ALPHA)', glow: 0.06, strength: 0.5, flicker: true });
518:   }
519: 
520:   dressStreet(r) {
521:     for (let tx = 2; tx < COLS - 2; tx++) {
522:       const d = this.districtAtPx(tx * TILE);
523:       if (this.isSolidTile(tx, STREET - 1)) {
524:         // inside a building footprint — skip
525:         continue;
526:       }
527:       const roll = r();
528:       if (roll < 0.09) {
529:         const types = d.style === 'military' ? ['barricade', 'sandbag', 'truck']
530:           : d.style === 'police' ? ['policeCar', 'barricade', 'car']
