playwright-cli -s=game reload >/dev/null 2>&1; playwright-cli -s=game eval "() => {
  const g = window.game; g.startRun('story');
  g.enemies.forEach(e => { if (!e.isBoss) e.alive = false; });
  g.player.invuln = 9999;
  const place = (x,y,frames=60) => { g.player.x=x; g.player.y=y; g.player.vx=0; g.player.vy=0; for(let i=0;i<frames;i++) g.update(1/60); return {x:+g.player.x.toFixed(1),y:+g.player.y.toFixed(1),grounded:g.player.grounded}; };
  const support = p => g.world.isSolidTile(Math.floor(p.x/24), Math.floor((p.y+4)/24));
  const out = {};
  out.nodes = [];
  for (const node of g.missionProps.nodes) {
    const p = place(node.x-36, node.y);
    const hp0 = node.hp;
    for (let i=0;i<6 && node.alive;i++) { g.player.attackCd=0; g.player.aim={x:node.x-g.player.x,y:(node.y-node.h/2)-g.player.centerY}; g.player.whip(); }
    out.nodes.push({support:support(node), stand:p, hp0, hp1:node.hp, alive:node.alive, count:g.flags.nodes});
  }
  const srv = g.missionProps.police;
  const sp = place(srv.x-56, srv.y);
  out.server = {support:support(srv), stand:sp, interact:g.tryInteract(g.player), flag:g.flags.police, hp:srv.hp, alive:srv.alive};
  const rc = g.missionProps.power;
  const rp = place(rc.x-48, rc.y);
  out.reactor = {support:support(rc), stand:rp, interact:g.tryInteract(g.player), flag:g.flags.power, hp:rc.hp, alive:rc.alive};
  const tc = g.missionProps.subway;
  const tp = place(tc.x-48, tc.y);
  out.transit = {support:support(tc), stand:tp, interact:g.tryInteract(g.player), flag:g.flags.subway, hp:tc.hp, alive:tc.alive};
  const gate = g.missionProps.checkpointGate;
  const gp = place(gate.x-120, gate.y);
  for (let i=0;i<25 && gate.alive;i++) { g.player.attackCd=0; g.player.aim={x:gate.x-g.player.x,y:(gate.y-gate.h/2)-g.player.centerY}; g.player.whip(); }
  out.gate = {support:support(gate), stand:gp, alive:gate.alive, flag:g.flags.gate};
  return out;
}" 2>&1 | tail -90

