// Input: keyboard, mouse and touch.
const KEYMAP = {
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  up: ['KeyW', 'ArrowUp'],
  down: ['KeyS', 'ArrowDown'],
  jump: ['Space'],
  attack: ['KeyJ'],
  grab: ['KeyK'],
  consume: ['KeyE'],
  dash: ['ShiftLeft', 'ShiftRight'],
  slam: ['KeyX'],
  spit: ['KeyF'],
  tendrils: ['KeyR'],
  camo: ['KeyC'],
  zip: ['KeyQ'],
  map: ['Tab'],
  pause: ['Escape'],
  interact: ['KeyE'],
  mute: ['KeyM'],
};

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressedKeys = new Set();
    this.mouse = { x: 480, y: 270, left: false, right: false, leftPressed: false, rightPressed: false, moved: false };
    this.touch = { stickX: 0, stickY: 0, stickActive: false, buttons: {}, pressed: new Set() };
    this.prev = {};
    this.stickPointer = null;
    this.canvasPoint = { x: 480, y: 270 };
    this.anyInput = false;

    window.addEventListener('keydown', (e) => {
      if (['Tab', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(e.code)) this.pressedKeys.add(e.code);
      this.keys.add(e.code);
      this.anyInput = true;
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouse.left = this.mouse.right = false;
      this.touch.buttons = {};
      this.touch.stickActive = false;
      this.touch.stickX = this.touch.stickY = 0;
    });

    canvas.addEventListener('mousemove', (e) => {
      const p = this.toCanvas(e.clientX, e.clientY);
      this.canvasPoint = p;
      this.mouse.x = p.x; this.mouse.y = p.y;
      this.mouse.moved = true;
    });
    canvas.addEventListener('mousedown', (e) => {
      e.preventDefault();
      const p = this.toCanvas(e.clientX, e.clientY);
      this.canvasPoint = p;
      if (e.button === 0) { this.mouse.left = true; this.mouse.leftPressed = true; }
      if (e.button === 2) { this.mouse.right = true; this.mouse.rightPressed = true; }
      this.anyInput = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.mouse.left = false;
      if (e.button === 2) this.mouse.right = false;
    });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    this._setupTouch();
  }

  toCanvas(clientX, clientY) {
    const r = this.canvas.getBoundingClientRect();
    const scale = Math.min(r.width / 960, r.height / 540);
    const ox = (r.width - 960 * scale) / 2;
    const oy = (r.height - 540 * scale) / 2;
    return {
      x: Math.max(0, Math.min(960, (clientX - r.left - ox) / scale)),
      y: Math.max(0, Math.min(540, (clientY - r.top - oy) / scale)),
    };
  }

  _setupTouch() {
    const zone = document.getElementById('stick-zone');
    const stick = document.getElementById('stick');
    const knob = document.getElementById('stick-knob');
    if (!zone) return;

  // dash
  if (this.state === 'dash') {
    this.dashTimer -= dt;
    this.vx = this.facing * 820;
    this.vy = 0;
    this.moveHorizontal(dt);
    this.dashDamage();
    if (this.dashTimer <= 0) { this.state = 'normal'; this.vx *= 0.35; }
    this.trail(dt);
    this.updateGrab(dt);
    this.handleActions(input, dt);
    return;
  }

  // crouch
  if (this.state === 'normal' && this.grounded && this.squeezeAllowed) {
    if (input.moveY > 0.4) {
      if (!this.crouch) {
        this.crouch = true;
        this.h = Math.min(this.h, 17);
      }
    } else if (this.crouch) {
      const nh = this.baseH * this.scale;
      if (!this.game.rectBlocked(this.x - this.w / 2, this.y - nh, this.w, nh)) {
        this.h = nh; this.crouch = false;
      }
    }
  } else if (this.crouch && this.state !== 'normal') {
    this.crouch = false;
    this.h = this.baseH * this.scale;
  }

  // movement states
  if (this.state === 'climb') {
    this.updateClimb(dt, input);
  } else if (this.state === 'ceiling') {
    this.updateCeiling(dt, input);
  } else {
    this.updateGround(dt, input);
  }

  this.handleActions(input, dt);
  this.updateGrab(dt);

  // fallback out of world
  if (this.y > this.game.world.height + 200) {
    this.damage(9999, this.game);
  }
  if (this.grounded) this.lastSafe = { x: this.x, y: this.y };
}

handleActions(input, dt) {
  if (this.consumeTimer > 0 || this.dead) return;
  if (input.pressed('attack') && this.attackCd <= 0) this.whip();
  if (input.down('grab') && this.grabCd <= 0) {
    if (!this.grabbed) this.tryGrab();
    else this.keepGrab = true;
  }
  if (!input.down('grab') && this.grabbed && this.grabHold) this.releaseGrab();
  if (input.pressed('interact')) {
    if (!this.game.tryInteract(this)) this.tryConsume();
  } else if (input.pressed('consume')) {
    this.tryConsume();
  }
  if (input.pressed('dash') && this.abilities.dash && this.energy >= 8 && this.dashTimer <= 0) this.dash();
  if (input.pressed('slam') && this.abilities.slam && this.energy >= 16 && this.slamCd <= 0) this.slam();
  if (input.pressed('spit') && this.abilities.spit && this.energy >= 12 && this.spitCd <= 0) this.spit();
  if (input.pressed('tendrils') && this.abilities.tendrils && this.energy >= 30 && this.tendrilCd <= 0) this.summonTendrils();
  if (input.pressed('camo') && this.abilities.camo && this.energy >= 22 && this.camoCd <= 0) this.toggleCamo();
  if (input.pressed('zip') && this.energy >= 6 && this.zipCd <= 0) this.zip();
}

updateGround(dt, input) {
  const speed = (this.crouch ? 95 : 215) * (this.level >= 3 ? 0.92 : 1) * (this.camoActive ? 1.08 : 1);
  const target = input.moveX * speed;
  }
  const prevTop = this.y - this.h;
  this.moveVertical(dt);
  // stick to wall
  if (this.climbSide < 0) {
    const tx = Math.floor((this.x - this.w / 2 - 3) / TILE);
    this.x = (tx + 1) * TILE + this.w / 2 + 0.5;
  } else {
    const tx = Math.floor((this.x + this.w / 2 + 3) / TILE);
    this.x = tx * TILE - this.w / 2 - 0.5;
  }
  if (input.pressed('jump')) {
    this.state = 'normal';
    this.vy = -470;
    this.vx = -this.climbSide * 260;
    this.climbSide = 0;
    this.game.audio.sfx('whip', this.x, this.y);
    return;
  }
  if (input.moveX * this.climbSide < -0.55) {
    this.state = 'normal';
    this.vy = 0;
    this.vx = input.moveX * 120;
    return;
  }
  // ceiling transition
  if (input.moveY < -0.3 && this.headBlocked()) {
    const cy = Math.floor((this.y - this.h - 2) / TILE);
    this.y = (cy + 1) * TILE + this.h;
    this.state = 'ceiling';
    this.vy = 0;
    this.game.particles.slime(this.x, this.y - this.h, 0);
  }
  // top/bottom of wall
  if (this.y - this.h < prevTop - 1 && this.headBlocked()) {
    const cy = Math.floor((this.y - this.h - 2) / TILE);
    this.y = (cy + 1) * TILE + this.h;
    this.state = 'ceiling';
  }
  this.trail(dt);
}

updateCeiling(dt, input) {
  const speed = 165 * (this.camoActive ? 1.1 : 1);
  this.vx = input.moveX * speed;
  this.vy = 0;
  this.moveHorizontal(dt);
  // remain attached to ceiling
  const cy = Math.floor((this.y - this.h - 2) / TILE);
  if (!this.game.rectBlocked(this.x - this.w * 0.32, this.y - this.h - 3, this.w * 0.64, 3)) {
    this.state = 'normal';
    this.grounded = false;
    this.vy = 40;
    return;
  }
  this.y = (cy + 1) * TILE + this.h;
  if (input.pressed('jump')) {
    this.state = 'normal';
    this.vy = 220; this.vx = input.moveX * 200;
    return;
  }
  if (input.moveY > 0.5) {
    this.state = 'normal'; this.grounded = false; this.vy = 120;
    return;
  }
  // Crawl freely along the ceiling. Drop with S / jump to reattach to a wall.
  this.trail(dt);
}

moveHorizontal(dt) {
  let dx = this.vx * dt;

  const target = input.moveX * speed;
  this.vx = lerp(this.vx, target, this.grounded ? 0.32 : 0.13);
  if (this.grounded && Math.abs(input.moveX) > 0.2) this.facing = input.moveX > 0 ? 1 : -1;
  this.vy += 1450 * dt;
  if (this.vy > 1000) this.vy = 1000;
  if (input.pressed('jump') && this.grounded && !this.crouch) {
    this.vy = -520;
    this.grounded = false;
    this.game.audio.sfx('whip', this.x, this.y);
    this.game.particles.slime(this.x, this.y, 0);
  }
  const prevGrounded = this.grounded;
  this.grounded = false;
  this.moveHorizontal(dt);
  this.moveVertical(dt);

  // wall cling / climb
  const leftWall = this.findWall(-1), rightWall = this.findWall(1);
  const into = (leftWall && input.moveX < -0.3) || (rightWall && input.moveX > 0.3);
  if (into && input.moveY < -0.25) {
    this.startClimb(leftWall ? -1 : 1);
  }
  if (this.grounded && input.moveY < -0.4 && (leftWall || rightWall) && into) {
    this.startClimb(leftWall ? -1 : 1);
  }
  if (!this.grounded && input.moveY < -0.4 && this.headBlocked()) {
    // direct ceiling grab
    const cy = Math.floor((this.y - this.h - 2) / TILE);
    this.y = (cy + 1) * TILE + this.h;
    this.state = 'ceiling';
    this.vy = 0; this.vx = 0;
  }
  if (this.grounded) this.trailTimer -= dt;
  this.trail(dt);
  if (this.vy > 0) this.grounded = false;
  if (this.grounded && prevGrounded) this.lastSafe = { x: this.x, y: this.y };
}

startClimb(side) {
  this.state = 'climb';
  this.climbSide = side;
  this.vy = 0; this.vx = 0;
  this.grounded = false;
  if (side < 0) {
    const tx = Math.floor((this.x - this.w / 2 - 3) / TILE);
    this.x = (tx + 1) * TILE + this.w / 2 + 0.5;
  } else {
    const tx = Math.floor((this.x + this.w / 2 + 3) / TILE);
    this.x = tx * TILE - this.w / 2 - 0.5;
  }
  this.game.particles.slime(this.x, this.y - this.h / 2, 0);
}

updateClimb(dt, input) {
  this.vy = input.moveY * 165;
  this.vx = 0;
  if (!this.findWall(this.climbSide)) {
    this.state = 'normal';
    this.grounded = false;
    return;
  }
  const prevTop = this.y - this.h;
  this.moveVertical(dt);
  // stick to wall
  if (this.climbSide < 0) {
    const tx = Math.floor((this.x - this.w / 2 - 3) / TILE);
    this.x = (tx + 1) * TILE + this.w / 2 + 0.5;
  } else {
    const tx = Math.floor((this.x + this.w / 2 + 3) / TILE);
    this.x = tx * TILE - this.w / 2 - 0.5;
  }

  _down(action) {
    const codes = KEYMAP[action] || [];
    for (const c of codes) if (this.keys.has(c)) return true;
    return false;
  }
  _pressed(action) {
    const codes = KEYMAP[action] || [];
    for (const c of codes) if (this.pressedKeys.has(c)) return true;
    return false;
  }

  get moveX() {
    let x = 0;
    if (this._down('left')) x -= 1;
    if (this._down('right')) x += 1;
    x += this.touch.stickX;
    if (Math.abs(x) < 0.18) x = 0;
    return Math.max(-1, Math.min(1, x));
  }
  get moveY() {
    let y = 0;
    if (this._down('up')) y -= 1;
    if (this._down('down')) y += 1;
    y += this.touch.stickY;
    if (Math.abs(y) < 0.22) y = 0;
    return Math.max(-1, Math.min(1, y));
  }

  down(action) {
    if (action === 'attack') return this._down('attack') || this.mouse.left || !!this.touch.buttons.whip;
    if (action === 'grab') return this._down('grab') || this.mouse.right || !!this.touch.buttons.grab;
    if (action === 'consume') return this._down('consume') || !!this.touch.buttons.consume;
    if (action === 'jump') return this._down('jump') || !!this.touch.buttons.jump;
    if (action === 'dash') return this._down('dash') || !!this.touch.buttons.dash;
    if (action === 'slam') return this._down('slam') || !!this.touch.buttons.slam;
    if (action === 'spit') return this._down('spit') || !!this.touch.buttons.spit;
    if (action === 'camo') return this._down('camo') || !!this.touch.buttons.camo;
    if (action === 'tendrils') return this._down('tendrils') || !!this.touch.buttons.tendrils;
    return this._down(action);
  }

  pressed(action) {
    if (action === 'attack') return this._pressed('attack') || this.mouse.leftPressed || this.touch.pressed.has('whip');
    if (action === 'grab') return this._pressed('grab') || this.mouse.rightPressed || this.touch.pressed.has('grab');
    if (action === 'consume') return this._pressed('consume') || this.touch.pressed.has('consume');
    if (action === 'jump') return this._pressed('jump') || this.touch.pressed.has('jump');
    if (action === 'dash') return this._pressed('dash') || this.touch.pressed.has('dash');
    if (action === 'slam') return this._pressed('slam') || this.touch.pressed.has('slam');
    if (action === 'spit') return this._pressed('spit') || this.touch.pressed.has('spit');
    if (action === 'camo') return this._pressed('camo') || this.touch.pressed.has('camo');
    if (action === 'tendrils') return this._pressed('tendrils') || this.touch.pressed.has('tendrils');
    if (action === 'zip') return this._pressed('zip') || this.touch.pressed.has('zip');
    if (action === 'interact') return this._pressed('interact') || this.touch.pressed.has('consume');
    return this._pressed(action);
  }

  // Call once at the end of each frame.
  endFrame() {
    this.pressedKeys.clear();
    this.mouse.leftPressed = false;
    this.mouse.rightPressed = false;
    this.mouse.moved = false;
    this.touch.pressed.clear();
  }
}

